#!/usr/bin/env node

// packages/lerna/src/cli.ts
import importLocal from "import-local";
import { createRequire } from "node:module";
var require2 = createRequire(import.meta.url);
if (importLocal(import.meta.filename)) {
  minimalInfoLog("cli", "using local version of lerna");
} else {
  const main = require2("./index.js");
  main(process.argv.slice(2));
}
function minimalInfoLog(prefix, message) {
  const stream = process.stderr;
  const green = "\x1B[32m";
  const magenta = "\x1B[35m";
  const reset = "\x1B[0m";
  const useColor = stream.isTTY;
  let output = "";
  if (useColor) {
    output += green;
  }
  output += "info";
  if (useColor) {
    output += reset;
  }
  if (prefix) {
    output += " ";
    if (useColor) {
      output += magenta;
    }
    output += prefix;
    if (useColor) {
      output += reset;
    }
  }
  output += ` ${message}`;
  stream.write(`${output}
`);
}
